var DictFaseTQ = ee.Dictionary({
  'CCDRU':1,
  'DECRETO':2,
  'NAO_INFORMADO':3,
  'PORTARIA':4,
  'RTID':5,
  'TITULADO':6,
  'TITULO_ANULADO':7,
  'TITULO_PARCIAL':8,
});

/**
 * Cria uma única imagem contendo bandas dinamicamente nomeadas,
 * onde cada banda corresponde a uma chave do dicionário e seu valor é constante.
 * 
 * @param {ee.Dictionary} dict O dicionário a ser transformado.
 * @returns {ee.Image} A imagem resultante com múltiplas bandas.
 */
function criarImagemDeDicionario(dict) {
  // 1. Obter as chaves (nomes das bandas) como uma Lista
  var keys = dict.keys();

  // 2. Mapear cada chave para a criação de uma banda constante
  // O resultado será uma ee.List, onde cada item é uma ee.Image constante.
  var listaImagensComBandas = keys.map(function(key) {
