// Visualizando uma das bandas como exemplo
Map.addLayer(imagemDeFases.select('CCDRU'), {min: 1, max: 1}, 'Banda CCDRU');
Map.addLayer(imagemDeFases.select('TITULADO'), {min: 6, max: 6}, 'Banda TITULADO');
```

