 * @param {object} data - Objeto contendo { min, media, max, chance }.
 * @returns {object} Objeto com os valores ligeiramente modificados.
 */
function atualizarValores(data) {
    // Fator de variação: +/- 10% (Math.random() * 0.2 - 0.1 resulta em um valor entre -0.1 e 0.1)
    const variacao = (1 + Math.random() * 0.2 - 0.1); 

    return {
        // Aplica a variação aos valores numéricos
        min: data.min * variacao,
        media: data.media * variacao,
        max: data.max * variacao,
        // Altera a chance dentro de um intervalo de -5% a +5%, garantindo um mínimo de 1%
        chance: Math.max(1, Math.min(100, data.chance + Math.floor(Math.random() * 11) - 5)) 
    };
}

/**
 * Gera a string formatada das estatísticas para um único jogo.
 * @param {string} nome - Nome do jogo.
 * @param {object} valores - Valores estatísticos atualizados.
 * @returns {string} A string formatada.
 */
function formatarEstatistica(nome, valores) {
    const { min, media, max, chance } = valores;
    return `*❲${nome}❳*\n• *Mínimo:* R$ ${min.toFixed(2)}\n• *Média:* R$ ${media.toFixed(2)}\n• *Máximo:* R$ ${max.toFixed(2)}\n• *Chance:* ${chance}%\n\n`;
}


/**
 * Gera o relatório completo de estatísticas, seja para um jogo específico ou para todos.
 * @param {string | null} jogo - O nome do jogo a ser exibido. Se for 'all', exibe todos.
 * @param {object} jogos - O objeto contendo todos os jogos e seus dados originais.
 * @returns {string} O relatório formatado.
 */
function gerarRelatorioEstatisticas(jogo, jogos) {
    const header = "🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n";

    if (jogo === 'all') {
        let resposta = header;

        Object.keys(jogos).forEach(nome => {
            const valoresAtualizados = atualizarValores(jogos[nome]);
            resposta += formatarEstatistica(nome, valoresAtualizados);
        });
        return resposta + "Observação: As porcentagens podem conter alguma divergência...";
    }

    const jogoData = jogos[jogo];
    if (!jogoData) return `❌ Jogo "${jogo}" não encontrado.`;

    const valoresAtualizados = atualizarValores(jogoData);

    return header + formatarEstatistica(jogo, valoresAtualizados) + "Observação: As porcentagens podem conter alguma divergência...";
}


// ==================================================
// 💾 GERENCIAMENTO DE DADOS (Inicialização de Arquivos)
// ==================================================

/**
 * Inicializa ou carrega os dados de relacionamentos.json.
 * @returns {object} O objeto contendo casamentos e namoros.
 */
function carregarRelacionamentos() {
    const casamento_json = './relacionamentos.json'; 

    if (!fs.existsSync(casamento_json)) {
        console.log("Arquivo de relacionamentos não encontrado. Criando um novo.");
        fs.writeFileSync(casamento_json, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
        return { casamentos: [], namoros: [] };
    }

    try {
        const data = fs.readFileSync(casamento_json, 'utf-8');
        const parsedData = JSON.parse(data);

        // Garante que a estrutura mínima exista
        if (!parsedData.casamentos || !parsedData.namoros) {
             console.warn("Estrutura incompleta em relacionamentos.json. Corrigindo.");
             fs.writeFileSync(casamento_json, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
             return { casamentos: [], namoros: [] };
        }
        return parsedData;

    } catch (error) {
        console.error("Erro ao ler ou parsear relacionamentos.json:", error);
        // Retorna um estado seguro em caso de erro
        return { casamentos: [], namoros: [] };
    }
}

/**
 * Carrega dados de Aki.json, ou um objeto vazio se não existir.
 * @returns {object} Os dados carregados de aki.json.
 */
function carregarAkiData() {
    const akiFilePath = './aki.json';
    if (fs.existsSync(akiFilePath)) {
        try {
            return JSON.parse(fs.readFileSync(akiFilePath, 'utf-8'));
        } catch (e) {
            console.error("Erro ao ler aki.json. Retornando dados vazios.", e);
            return {};
        }
    }
    return {};
}


